/// <summary>
/// MPJ_21275_BackOrders
/// Extension of SalesTable form datasource of SalesLine
/// </summary>
[ExtensionOf(formDataSourceStr(SalesTable, SalesLine))]
final class METSalesTableFormSalesLineDS_Extension
{
}

Method.Source:
    /// <summary>
    /// MPJ_21275_BackOrders
    /// Based up on the SO header, Item master and Site Allow back orders check box Sales line will be activated
    /// </summary>
    /// <returns>current record</returns>
    public int active()
    {
        SalesLine           salesLine           =  this.formRun().dataSource(formDataSourceStr(SalesTable, SalesLine)).cursor(); 
        SalesTable          salesTable;
        
        select firstonly METTobaccoLicenceValidationRequired, METValidTobaccoLicence, METCustTobaccoReasonCode from salesTable where salesTable.SalesId == salesLine.SalesId;
        if(salesTable.METTobaccoLicenceValidationRequired == NoYes::Yes
            && salesTable.METValidTobaccoLicence == NoYes::Yes
                && METCustParameters::Find().TobaccoFilterCodes == WHSInventTable::find(salesLine.ItemId, false).FilterCode[1]
                    && salesTable.METCustTobaccoReasonCode)
        {
            this.object(fieldNum(SalesLine, Blocked)).allowEdit(false);
        }

        return next active();
    }

    void itemIdModified()
    {
        InventItemSalesSetup    inventItemSalesSetup;      
        FormDataSource          datasourceInventDim      = this.formRun().dataSource(formDataSourceStr(SalesTable,InventDim)) as FormDataSource ;
        SalesLine               salesLine       = this.formRun().dataSource().cursor();
        InventDim               inventDimLoc    = datasourceInventDim.cursor();
        InventDim               inventDimSales;

        next itemIdModified();

        //MPJ_17845_PBMSProductMDRItemSite on 04 March 2022 by Sathish - Start
        select firstonly inventItemSalesSetup
            where inventItemSalesSetup.ItemId == salesLine.ItemId
                join RecId from inventDimSales
                    where inventDimSales.inventDimId == inventItemSalesSetup.InventDimId
                        &&  inventDimSales.InventSiteId == inventDimLoc.InventSiteId;

        salesLine.SalesUnit  = inventItemSalesSetup.METSalesUnit;
        //MPJ_17845_PBMSProductMDRItemSite - End
    }
